package com.fakelegacy.order.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class TaxUtils {

    private static final BigDecimal REDUCED = new BigDecimal("0.055");
    private static final BigDecimal NORMAL = new BigDecimal("0.20");

    private TaxUtils() {
    }

    public static BigDecimal vatRateFor(String category) {
        if ("FOOD".equals(category) || "BOOKS".equals(category)) {
            return REDUCED;
        }
        return NORMAL;
    }

    public static BigDecimal round2(BigDecimal v) {
        return v.setScale(2, RoundingMode.HALF_UP);
    }

    public static BigDecimal withVat(BigDecimal ht, BigDecimal vatRate) {
        return round2(ht.multiply(BigDecimal.ONE.add(vatRate)));
    }
}
